       transform: translateY(-1px);
       box-shadow: 0 16px 30px rgba(22, 95, 224, 0.26);
     }

     .submit-btn:focus {
       outline: 3px solid transparent;
       box-shadow: 0 0 0 4px rgba(11, 103, 255, 0.24), 0 12px 24px rgba(22, 95, 224, 0.25);
     }

     .status {
       margin: 0;
       min-height: 1.5rem;
       font-weight: 600;
       color: var(--color-success);
     }

