         h("p", {}, "Tell us who you are and we will follow up by email or phone as needed.")
       );

       const form = h("form", { id: "support-form", novalidate: "" });
       const status = h("p", { className: "status", id: "form-status", "aria-live": "polite" });

       const nameField = Field({
         id: "full-name",
         label: "Full name",
         type: "text",
         autocomplete: "name",
         required: true,
         helperText: "Enter the name you use with your account.",
       });

       const emailField = Field({
         id: "email-address",
         label: "Email address",
         type: "email",
         autocomplete: "email",
         required: true,
         helperText: "We will reply to this address.",
       });

       const phoneField = Field({
         id: "phone-number",
         label: "Phone number",
         type: "tel",
         autocomplete: "tel",
         required: false,
         inputMode: "tel",
         helperText: "Optional. Use format +1 555 123 4567 or 555-123-4567.",
       });

       const footer = h("div", { className: "form-footer" },
         h("p", { className: "field-help" }, "Fields marked with * are required."),
         h("button", { className: "submit-btn", type: "submit" }, "Send message")
       );

       const fields = [nameField, emailField, phoneField];
       fields.forEach(({ field }) => form.appendChild(field));
       form.append(status, footer);

       const validators = {
         "full-name": value => !value.trim() ? "Error: Full name is required." : "",
         "email-address": value => {
           if (!value.trim()) return "Error: Email address is required.";
           const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
           return emailPattern.test(value.trim()) ? "" : "Error: Enter a valid email address, like name@example.com.";
         },
         "phone-number": value => {
           const cleaned = value.trim();
           if (!cleaned) return "";
           const phonePattern = /^\+?[0-9().\-\s]{7,}$/;
           return phonePattern.test(cleaned) ? "" : "Error: Enter a phone number in a valid format, like +1 555 123 4567.";
         }
